 document.addEventListener('DOMContentLoaded',function(){console.log('Araucaria website loaded');if(typeof jarallax!=='undefined'){jarallax(document.querySelectorAll('.jarallax'),{speed:0.2,noAndroid:false,noIos:false});}const tooltipTriggerList=[].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));tooltipTriggerList.map(function(tooltipTriggerEl){return new bootstrap.Tooltip(tooltipTriggerEl);});document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){e.preventDefault();const target=document.querySelector(this.getAttribute('href'));if(target){target.scrollIntoView({behavior:'smooth'});}});});const currentLocation=location.pathname;const navLinks=document.querySelectorAll('.navbar-nav .nav-link');navLinks.forEach(link=>{const href=link.getAttribute('href');if(currentLocation.includes(href.replace('../','').replace('.html',''))){link.classList.add('active');}else{link.classList.remove('active');}});});function showNotification(message,type='info'){console.log(`[${type.toUpperCase()}]${message}`);}